// This Function node expects each item.json to have the raw structure from your HTTP transcript API.
// For each item, we extract VideoId, parse transcript blocks, and produce segments + full text.

return items.map(item => {
  const rawData = item.json;

  // 1. VideoId: adjust according to how your rawData provides it. 
  //    Often it's rawData.id or rawData.VideoId. Here we use rawData.id:
  const VideoId = rawData.id || rawData.VideoId || null;

  // 2. Extract the transcript blocks array:
  //    rawData.tracks is an array; we take the first track with transcript if present
  let transcriptBlocks = [];
  if (Array.isArray(rawData.tracks) && rawData.tracks.length > 0) {
    // find a track with a transcript array
    const track = rawData.tracks.find(t => Array.isArray(t.transcript));
    if (track) {
      transcriptBlocks = track.transcript;
    }
  }

  // 3. Build transcriptSegments: parse start/dur as numbers
  const transcriptSegments = transcriptBlocks.map(block => {
    // parseFloat may yield NaN if block.start/dur missing; you can default to 0 in that case
    const startNum = parseFloat(block.start);
    const durNum = parseFloat(block.dur);
    return {
      start: isNaN(startNum) ? 0 : startNum,
      dur: isNaN(durNum) ? 0 : durNum,
      text: block.text || ""
    };
  });

  // 4. Build a single concatenated transcriptText, e.g. "[0.12] text"
  const transcriptText = transcriptSegments
    .map(seg => {
      // format start to two decimals
      const t = (typeof seg.start === "number") ? seg.start.toFixed(2) : "0.00";
      return `[${t}] ${seg.text}`;
    })
    .join("\n");

  // 5. createdAt timestamp
  const createdAt = new Date().toISOString();

  // 6. Return one output item per input item, containing all fields for MongoDB
  return {
    json: {
      VideoId,
      transcriptText,
      transcriptSegments,
      createdAt
    }
  };
});

