  const match = url.match(regex);
  return match ? match[1] : null;
}

function extractDriveID(url) {
  if (!url || typeof url !== 'string') return null;

  // Regex for Google Drive file IDs (28+ characters)
  const regex = /(?:drive\.google\.com\/(?:file\/d\/|uc\?id=|open\?id=)|docs\.google\.com\/(?:file\/d\/|uc\?id=)|drive\.usercontent\.google\.com\/download\?id=|video\.google\.com\/get_player\?.*?docid=)([a-zA-Z0-9_-]{28,})/;
  const match = url.match(regex);
  return match ? match[1] : null;
}

function getLinkType(url) {
  if (!url || typeof url !== 'string') return 'other';

  if (/^https?:\/\/(www\.)?(youtube\.com|youtu\.be)\//i.test(url)) {
    return 'youtube';
  } else if (/^https?:\/\/(drive\.google\.com|docs\.google\.com|drive\.usercontent\.google\.com|video\.google\.com)\//i.test(url)) {
    return 'drive';
  }

  return 'other';
}

const linkType = getLinkType(url);
const VideoId = extractYouTubeID(url);
const driveId = extractDriveID(url);

