// Clone the second item and add type
const updatedSecondItem = {
  ...items[1],
  json: {
    ...items[1].json,
    type: typeValue
  }
};

// Return only the modified second object
return [updatedSecondItem];

// N8N Code Node - Transform transcript data for MongoDB
// Input: Current transcript structure from backend
// Output: MongoDB-ready format

// Get the input data from the previous node
const inputData = $input.all();

// Process each item (in case there are multiple)
const transformedItems = inputData.map(item => {
  const data = item.json.result || item.json;

  // Extract basic info
  const VideoId = data.VideoId;
  const segments = data.segments || [];

  // Generate transcriptText with timestamps
  let transcriptText = '';
  const transformedSegments = [];

  segments.forEach(segment => {
    // Add to transcript text with timestamp format [start_time]
    const startTime = parseFloat(segment.start).toFixed(2);
    transcriptText += `[${startTime}] ${segment.text}\n`;

    // Transform segment structure
    const transformedSegment = {
      start: parseFloat(segment.start),
      dur: parseFloat(segment.end) - parseFloat(segment.start), // Calculate duration
      text: segment.text
    };

    transformedSegments.push(transformedSegment);
  });

  // Remove trailing newline
  transcriptText = transcriptText.trim();

  // Create the MongoDB document structure
  const mongoDocument = {
    VideoId: VideoId,
    createdAt: new Date().toISOString(),
    transcriptText: transcriptText,
    transcriptSegments: transformedSegments
  };

  return {
    json: mongoDocument
  };
});

// Return the transformed data
return transformedItems;

return [
  {
    json: {
      // Pull VideoId straight off the incoming data
      VideoId:   $json["VideoId"],

      // Timestamp it now
      createdAt: new Date().toISOString(),

      // Copy over the full transcript text
      transcriptText:    $json["transcriptText"],

      // Include transcriptSegments if present, otherwise an empty array
      transcriptSegments: $json["transcriptSegments"] || []
    }
  }
];

// 1. Extract the two merged JSON objects
const original = items[0]?.json || {};
const mongo    = items[1]?.json || {};

// 2. Detect if the Mongo object actually has any keys
const hasMongo = Object.keys(mongo).length > 0;

// 3. Build a single result object:
//    - resultCount = 1 if only original exists, 2 if Mongo data exists
//    - spread in original fields always
//    - spread in mongo fields only if present
const result = {
  resultCount: hasMongo ? 2 : 1,
  ...original,
  ...(hasMongo ? mongo : {})
};

// 4. Return as single‑item array
return [{ json: result }];

